// User Configuration:
const chunkSize = 1500; // Target size of each text chunk
const chunkOverlap = 150; // Number of characters to overlap between chunks
// Path to extracted text from the HTTPRequest_ExtractText node.
// Adjust this based on the actual response structure of your text extraction API.
// Examples: $json.text, $json.extracted_content, $json.data.text_field
const extractedText = $json.text; // Assuming output of HTTPRequest_ExtractText is like {"text": "..."}

// --- Helper function to determine document type ---
function getDocumentType(mimeType) {
  if (mimeType === 'application/pdf') {
    return 'PDF';
  } else if (mimeType === 'application/vnd.openxmlformats-officedocument.wordprocessingml.document' || mimeType === 'application/msword') {
    return 'Word';
  }
  return 'Unknown';
}

// --- Main Chunking Logic ---
const results = [];
if (extractedText && typeof extractedText === 'string') {
  let i = 0;
  let chunkCounter = 0;
  while (i < extractedText.length) {
    const chunkEnd = Math.min(i + chunkSize, extractedText.length);
    const textChunk = extractedText.substring(i, chunkEnd);

    // Retrieve original file metadata from the input item.
    // This assumes the Code node is receiving the item that originated from GoogleDrive_ListFiles,
    // potentially merged with data from GoogleDrive_DownloadFile and HTTPRequest_ExtractText.
    // Ensure your workflow passes these fields correctly.
    // The $item(0) or similar might be needed if data is split. For simplicity, direct access is assumed.
    // Check n8n documentation if data from earlier nodes isn't directly in $json.
    const fileData = $item(0).$json; // Assumes data from the node that started this execution branch (SplitInBatches)

    const metadata = {
      file_id: fileData.id, // From GoogleDrive_ListFiles
      file_name: fileData.name, // From GoogleDrive_ListFiles
      document_type: getDocumentType(fileData.mimeType), // From GoogleDrive_ListFiles
      creation_date: fileData.createdTime, // From GoogleDrive_ListFiles
      modification_date: fileData.modifiedTime, // From GoogleDrive_ListFiles
      source_url: fileData.webViewLink, // From GoogleDrive_ListFiles
      chunk_sequential_id: `chunk_${chunkCounter}`,
      chunk_text: textChunk, // Storing the chunk text itself in metadata for Pinecone
      // page_number_start: null, // Placeholder if your extraction API provides page numbers
      // page_number_end: null,   // Placeholder
      // keywords: "", // Optional: Could be generated by another LLM call
      // summary_chunk: "" // Optional: Could be generated by another LLM call
    };

    results.push({
      text_chunk: textChunk,
      metadata_enriched: metadata
    });

    i += chunkSize - chunkOverlap;
    if (i >= extractedText.length && chunkEnd === extractedText.length) {
        // Handles the case where the loop condition might prevent the last chunk if it's smaller
        // and overlap causes 'i' to exceed length. This ensures last part is always captured.
        break; 
    }
    chunkCounter++;
  }
} else {
  // Handle cases where text might be missing or not a string
  // You might want to log an error or return an empty array
  console.warn(`No text found or invalid format for item: ${$json.file_id || 'Unknown ID'}`);
  // return []; // Option to return empty if no text
}

// The Code node should return an array of items.
// Each item will be processed by subsequent nodes.
return results;
